import data from "@/content/photos.json";

/** Curated, freely licensed photos (Wikimedia Commons), generated by
 * scripts/fetch_photos.py from scripts/photos.manifest.json. */
export interface PhotoCredit {
  src: string;
  srcSmall: string;
  width: number;
  height: number;
  focus: string;
  alt: { en: string; fr: string };
  title: string;
  author: string;
  license: string;
  licenseUrl: string | null;
  source: string;
}

const PHOTOS = data as Record<string, PhotoCredit>;

export function getPhoto(key: string): PhotoCredit | null {
  return PHOTOS[key] ?? null;
}

export function allPhotos(): [string, PhotoCredit][] {
  return Object.entries(PHOTOS);
}

export function photoAlt(photo: PhotoCredit, locale: string): string {
  return locale === "fr" ? photo.alt.fr : photo.alt.en;
}

/** "Trip type" filters mapped onto destination tags. */
export const MOODS = {
  beach: ["beach", "coast", "sun"],
  city: ["city"],
  nature: ["nature", "outdoors", "adventure"],
  culture: ["culture", "history", "food", "markets"],
} as const;
export type Mood = keyof typeof MOODS;

export function isMood(value: string | undefined): value is Mood {
  return value !== undefined && value in MOODS;
}

export function matchesMood(tags: string[], mood: Mood): boolean {
  return tags.some((t) => (MOODS[mood] as readonly string[]).includes(t));
}

/** Montréal–Trudeau: the home hub for globe routes and flight-time estimates. */
export const HUB = { iata: "YUL", latitude: 45.4678, longitude: -73.7423 } as const;
